WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time_2 FROM web_events WHERE event_time >= DATE '2023-10-06') SELECT *, LAG(days_since_event_time_2, 1, 0) OVER (PARTITION BY page ORDER BY days_since_event_time, id) AS prev_days_since_event_time_2, DENSE_RANK() OVER (PARTITION BY session_id ORDER BY duration_sec DESC) AS duration_sec_dense_rank, FIRST_VALUE(duration_sec, TRUE) OVER (PARTITION BY event_type, session_id ORDER BY days_since_event_time_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, AVG(duration_sec) OVER w_hist AS duration_sec_avg_2, SUM(days_since_event_time_2) OVER (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_days_since_event_time_2 FROM base WINDOW w_hist AS (PARTITION BY session_id, event_type ORDER BY days_since_event_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
